/* Non-destructive views over existing briefing and sortie records. Titles never identify a flight. */
(function(root){'use strict';
const clone=v=>JSON.parse(JSON.stringify(v));
const reference=id=>'FD-'+String(id||'unsaved').replace(/[^a-z0-9]/gi,'').slice(0,10).toUpperCase();
const briefingFlightId=r=>typeof r.flightId==='string'&&r.flightId?r.flightId:typeof r.missionId==='string'&&r.missionId?r.missionId:'legacy-brief-'+r.id;
function groups(briefings,sorties){const map=new Map(),byBrief=new Map();function group(id){if(!map.has(id))map.set(id,{id,reference:reference(id),briefings:[],sorties:[],latest:null,projectTitle:'',missionTitle:'',status:'PLANNED',lastActivity:null,legacy:false});return map.get(id);}
for(const b of briefings){const id=briefingFlightId(b),g=group(id);g.briefings.push(b);byBrief.set(b.id,id);g.legacy ||= !b.missionId&&!b.flightId;}
for(const s of sorties){const id=s.missionId||byBrief.get(s.briefingId)||s.briefing?.missionId||'legacy-sortie-'+s.id,g=group(id);g.sorties.push(s);g.legacy ||= !s.missionId;}
for(const g of map.values()){g.briefings.sort((a,b)=>(Date.parse(a.savedAt)||0)-(Date.parse(b.savedAt)||0));g.latest=g.briefings.at(-1)||g.sorties.at(-1)?.briefing||null;g.projectTitle=g.latest?.projectTitle||g.sorties.at(-1)?.projectTitle||'Untitled project';g.missionTitle=g.latest?.missionTitle||g.sorties.at(-1)?.missionTitle||'Untitled flight';const phases=g.sorties.map(s=>s.phase);g.status=phases.includes('AIRBORNE')?'AIRBORNE':g.sorties.length>1?'LEGACY_MULTIPLE':phases[0]||'PLANNED';g.lastActivity=[...g.briefings.map(b=>b.savedAt),...g.sorties.flatMap(s=>[s.createdAt,...s.events.map(e=>e.recordedAt),...s.debriefs.map(d=>d.recordedAt)])].filter(Boolean).sort((a,b)=>(Date.parse(a)||0)-(Date.parse(b)||0)).at(-1)||null;g.canResume=g.status==='PLANNED'&&!!g.latest;}
return [...map.values()].sort((a,b)=>(Date.parse(b.lastActivity)||0)-(Date.parse(a.lastActivity)||0));}
const statusLabel=s=>({PLANNED:'Planned · briefing can be resumed',GROUND:'Ground log · not airborne',AIRBORNE:'In flight',LANDED:'Landed · debrief pending',DEBRIEF_COMPLETE:'Complete · debrief saved',CANCELLED:'Cancelled · not flown',POSTPONED:'Postponed · not flown',OUTCOME_UNKNOWN:'Outcome/time unresolved',LEGACY_MULTIPLE:'Legacy record · multiple sorties retained'})[s]||s;
function content(record){const out=clone(record);for(const k of ['id','savedAt','revisionNumber'])delete out[k];if(out.airspace)delete out.airspace.capturedAt;return JSON.stringify(out);}
function bundle(group,{exportedAt,appVersion,drafts=null}={}){if(!group)throw Error('Select a saved flight');return{format:'flightdesk-flight-record',version:1,flightId:group.id,reference:group.reference,exportedAt:exportedAt||new Date().toISOString(),exporterAppVersion:appVersion||'not recorded',briefings:clone(group.briefings),sorties:clone(group.sorties),debriefDrafts:drafts?clone(drafts):null,notice:'One flight identity with its saved briefing revisions, flight events and post-flight revisions. Any debrief draft is unfinished work, not a saved debrief revision. Local records are not independently verified or tamper-proof.'};}
function asBackup(value){if(!value||value.format!=='flightdesk-flight-record'||value.version!==1||typeof value.flightId!=='string'||!Array.isArray(value.briefings)||!Array.isArray(value.sorties)||value.briefings.length+value.sorties.length===0)throw Error('Invalid complete flight record');for(const b of value.briefings)if(b.flightId&&b.missionId&&b.flightId!==b.missionId)throw Error('Conflicting flight identity in briefing');const all=groups(value.briefings,value.sorties);if(all.length!==1||all[0].id!==value.flightId)throw Error('Flight record contains unrelated flight identities');if(new Set(value.briefings.map(b=>b.id)).size!==value.briefings.length||new Set(value.sorties.map(s=>s.id)).size!==value.sorties.length)throw Error('Duplicate record IDs in flight bundle');for(const s of value.sorties)if(s.briefingId&&!value.briefings.some(b=>b.id===s.briefingId)&&s.briefing?.id!==s.briefingId)throw Error('Launch briefing reference is missing');const profiles={version:1,pilots:[],operators:[],batteries:[],removedBatteries:[],batteryChanges:[]},add=(list,r)=>{if(r&&!list.some(p=>p.key===r.key))list.push(clone(r));};for(const r of [...value.briefings,...value.sorties.map(s=>s.briefing).filter(Boolean)]){add(profiles.pilots,r.pilot);add(profiles.operators,r.operator);add(profiles.batteries,r.battery);}const settings={};if(value.sorties.length)settings['flightdesk-sorties-v1']=JSON.stringify({version:1,sorties:value.sorties});if(value.debriefDrafts){if(value.debriefDrafts.version!==1||!value.debriefDrafts.drafts||Object.keys(value.debriefDrafts.drafts).some(id=>!value.sorties.some(s=>s.id===id)))throw Error('Debrief draft is not linked to this flight');}if(value.debriefDrafts)settings['flightdesk-debrief-drafts-v1']=JSON.stringify(value.debriefDrafts);return{format:'flightdesk-backup',version:1,profiles,flights:{version:1,records:value.briefings},settings};}
function reportHTML(group,options={}){const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),data=bundle(group,options);return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flight record '+escape(group.reference)+'</title><style>body{font:16px/1.5 system-ui;max-width:1000px;margin:30px auto;padding:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}article{break-inside:avoid;border-top:1px solid #aaa;padding-top:1rem}</style></head><body><h1>'+escape(group.projectTitle)+' / '+escape(group.missionTitle)+'</h1><p>'+escape(group.reference)+' · '+escape(statusLabel(group.status))+'</p><p>Full flight ID: '+escape(group.id)+'</p><p>'+escape(data.notice)+'</p><h2>Pre-flight briefings · '+group.briefings.length+' saved revision(s)</h2>'+group.briefings.map((b,i)=>'<article><h3>Briefing revision '+(i+1)+' · '+escape(b.savedAt)+'</h3><p>Snapshot '+escape(b.id)+' · '+escape(b.readiness?.recommendation||b.readiness?.status||'not recorded')+' at save</p><pre>'+escape(JSON.stringify(b,null,2))+'</pre></article>').join('')+'<h2>Flight and post-flight · '+group.sorties.length+' recorded sortie(s)</h2>'+group.sorties.map(s=>'<article><h3>'+escape(statusLabel(s.phase))+'</h3><p>Launch briefing: '+escape(s.briefingId)+' · actual take-off '+escape(s.takeoffAt||'not recorded')+' · landing '+escape(s.landingAt||'not recorded')+'</p><table><thead><tr><th>Event time · UTC</th><th>Event</th><th>Observation / action</th></tr></thead><tbody>'+s.events.map(e=>'<tr><td>'+escape(e.occurredAt||e.recordedAt)+'</td><td>'+escape(e.type)+'</td><td>'+escape((e.notes||'')+(e.type==='landing'&&e.durationSeconds!=null?' · Take-off '+e.takeoffAt+' · Landing '+e.landingAt+' · Duration '+e.durationSeconds.toFixed(1)+' seconds':''))+'</td></tr>').join('')+'</tbody></table><pre>'+escape(JSON.stringify(s,null,2))+'</pre></article>').join('')+(data.debriefDrafts?'<h2>Unfinished debrief draft · not a saved revision</h2><pre>'+escape(JSON.stringify(data.debriefDrafts,null,2))+'</pre>':'')+'<p>Exported '+escape(data.exportedAt)+' · app '+escape(data.exporterAppVersion)+'. Keep JSON for restoration; HTML can be printed as PDF.</p></body></html>';}
const api={reference,briefingFlightId,groups,statusLabel,content,bundle,asBackup,reportHTML};root.FLIGHT_RECORDS=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
